def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # Find position of each value
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # BFS with priority queue by path lexicographic order
    import heapq
    # Each state: (path_tuple, current_pos)
    # Start from all cells, but we can optimize by starting from smallest values
    # Actually, the first element must be 1 (global minimum)
    start = pos[1]
    pq = [([1], start)]
    visited = {}  # (pos, length) -> best path prefix

    while pq:
        path, (x, y) = heapq.heappop(pq)
        if len(path) == k:
            return path
        # Expand neighbors
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                state_key = ((nx, ny), len(new_path))
                if state_key not in visited or tuple(new_path) < visited[state_key]:
                    visited[state_key] = tuple(new_path)
                    heapq.heappush(pq, (new_path, (nx, ny)))

    # Should never reach here given problem guarantees
    return []

