    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # Find position of 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break

    # Find the minimum neighbor of 1
    min_neighbor = float('inf')
    for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
        ni, nj = start[0]+di, start[1]+dj
        if 0 <= ni < n and 0 <= nj < n:
            min_neighbor = min(min_neighbor, grid[ni][nj])

    result = [1]
    if k == 2:
        result.append(min_neighbor)
        return result

    # For k > 2, after first two steps, we oscillate between 1 and min_neighbor
    # But we need to check if there's a better second step
    # Actually, the optimal is: 1 -> min_neighbor -> 1 -> min_neighbor -> ...
    # But we need to verify if starting with 1 -> min_neighbor is optimal
    # Since 1 is the smallest, first element is 1. Second must be min_neighbor.
    # Then third: from min_neighbor, the smallest neighbor is min(1, other neighbors)
    # Since 1 is the smallest, third is 1. And so on.

