    nums = operand[:]
    i = 0
    while i < len(ops):
        if ops[i] == '**':
            nums[i] = apply('**', nums[i], nums[i+1])
            del nums[i+1]
            del ops[i]
        else:
            i += 1

    # Handle multiplication and floor division (left-associative)
    i = 0
    while i < len(ops):
        if ops[i] in ('*', '//'):
            nums[i] = apply(ops[i], nums[i], nums[i+1])
            del nums[i+1]
            del ops[i]
        else:
            i += 1

    # Handle addition and subtraction (left-associative)
